import express from 'express';
import compression from 'compression';

const app = express();
app.use(compression({ threshold: 1024 }));  // solo respuestas > 1 KB

import pg from 'pg';

const pool = new pg.Pool({
  max: 10,                        // conexiones como máximo
  idleTimeoutMillis: 30000,       // cerrar las inactivas
  connectionTimeoutMillis: 2000   // espera máxima por una conexión
});

app.get('/api/productos', async (req, res) => {
  const { rows } = await pool.query('SELECT id, nombre FROM productos LIMIT 20');
  res.json(rows);
});

